let authUser=null,accountData={orders:[],bookings:[],owners:[],restaurants:[]},localMailMode=false;
const accountRoute=['/account','/admin'].includes(location.pathname);
let registerAsAdmin=false,orderSubmitting=false;
async function api(url,method='GET',data){
  const response=await fetch(url,{method,credentials:'same-origin',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});
  let result;try{result=await response.json()}catch{throw Error('Сервер недоступен. Попробуйте ещё раз.')}
  if(!response.ok){const error=Error(result.error||'Не удалось выполнить запрос');error.status=response.status;throw error}return result;
}
function authFrame(content){$('#app').innerHTML=`<main class="auth-shell"><aside class="auth-story"><a class="logo" href="/">${icon('restaurant')}dayin<span>.</span></a><div><div class="eyebrow">ДЛЯ РЕСТОРАНОВ И КАФЕ</div><h1>Больше времени<br>для ваших гостей.</h1><p>Меню, заказы и бронирования<br>в одном личном кабинете.</p><div class="auth-steps"><span>01 &nbsp; Регистрация заведения</span><span>02 &nbsp; Письмо с доступом</span><span>03 &nbsp; Ваш личный кабинет</span></div></div><small>Dayin · Атырау</small></aside><section class="auth-main">${languageControl()}<a class="back" href="/">← Вернуться к заведениям</a><div class="auth-card">${content}</div><small class="muted">Доступ к данным только у владельца заведения</small></section></main>`}
function formError(form,error){const field=form.querySelector('[role="alert"]');if(field){field.textContent=error.message;field.hidden=false}else toast(error.message)}
async function submitAuth(event,action){event.preventDefault();const form=event.target,button=form.querySelector('button[type="submit"]');button.disabled=true;const old=button.textContent;button.textContent='Подождите…';try{await action(Object.fromEntries(new FormData(form)))}catch(e){formError(form,e)}finally{button.disabled=false;button.textContent=old}}
function registration(){registerAsAdmin=false;authFrame(`<div class="eyebrow">ПОДКЛЮЧЕНИЕ ЗАВЕДЕНИЯ</div><h1>Давайте познакомимся</h1><p>Укажите почту и ФИО владельца. Логин, временный пароль и ссылка на кабинет придут в письме.</p>${registrationForm()}<p class="auth-help">Уже зарегистрированы? Откройте ссылку на личный кабинет из вашего письма.</p>`)}
function registrationForm(){return `<form class="form" onsubmit="submitAuth(event,registerAccount)"><label>ФИО владельца<input name="name" required maxlength="120" autocomplete="name" placeholder="Фамилия Имя Отчество"></label><label>Электронная почта<input name="email" type="email" required maxlength="254" autocomplete="email" placeholder="you@restaurant.kz"></label><label>Название ресторана или кафе<input name="restaurantName" required maxlength="80" placeholder="Название заведения"></label><div class="form-error" role="alert" hidden></div><button class="primary" type="submit">Зарегистрировать заведение →</button><p class="auth-help">При первом входе нужно будет создать собственный пароль.</p></form>`}
async function registerAccount(fields){const result=await api(registerAsAdmin?'/api/admin/register':'/api/auth/register','POST',fields);if(registerAsAdmin){$('#modal').close();await refreshCatalog();await refreshAccount();render();toast(result.delivery==='local'?'Заведение зарегистрировано. Письмо в локальной почте.':'Заведение зарегистрировано. Письмо передано почтовому сервису.');return}authFrame(`<div class="success-mark">${icon('bag')}</div><div class="eyebrow">РЕГИСТРАЦИЯ ЗАВЕРШЕНА</div><h1>${result.delivery==='local'?'Учётная запись создана':'Проверьте вашу почту'}</h1><p>${result.delivery==='local'?'Письмо подготовлено в локальном режиме и не отправлено на настоящую почту.':'Письмо с доступом передано почтовому сервису.'}</p><div class="panel"><strong>${esc(fields.email)}</strong><p>В письме вы найдёте логин, временный пароль и ссылку на ваш личный кабинет.</p></div>${result.delivery==='local'?'<a class="primary auth-link" href="/dev/mail" target="_blank" rel="noopener">Открыть локальное письмо ↗</a>':'<p class="auth-help">Если письмо не появилось, проверьте папку «Спам».</p>'}<a class="secondary auth-link" href="/">Вернуться к заведениям</a>`)}
function renderAccount(){if(authUser?.role==='customer')authUser=null;if(authUser?.mustChangePassword){changePassword();return}if(authUser){if(location.pathname==='/admin'&&authUser.role!=='admin'){authFrame('<h1>Доступ ограничен</h1><p>Этот раздел доступен только администратору платформы.</p><a class="primary auth-link" href="/account">Перейти в свой кабинет</a>');return}openWorkspace();return}authFrame(`<div class="eyebrow">ЛИЧНЫЙ КАБИНЕТ ${location.pathname==='/admin'?'АДМИНИСТРАТОРА':'ЗАВЕДЕНИЯ'}</div><h1>Рады видеть вас</h1><p>Введите логин и пароль из письма. При первом входе мы попросим вас сменить пароль.</p><form class="form" onsubmit="submitAuth(event,login)"><label>Логин — электронная почта<input name="email" type="email" required autocomplete="username" maxlength="254" placeholder="Почта, указанная при регистрации"></label><label>Пароль<input name="password" type="password" required maxlength="128" autocomplete="current-password"></label><div class="form-error" role="alert" hidden></div><button class="primary" type="submit">Войти в личный кабинет →</button></form><p class="auth-help">Если временный пароль истёк, обратитесь к администратору платформы.</p>`)}
async function login(fields){const result=await api('/api/auth/login','POST',{...fields,audience:'business'});authUser=result.user;if(authUser.mustChangePassword){changePassword();return}await refreshAccount();renderAccount()}
function changePassword(){authFrame(`<div class="eyebrow">ПЕРВЫЙ ВХОД</div><h1>Создайте ваш пароль</h1><p>${esc(authUser.name)}, временный пароль выполнил свою задачу. Задайте новый, чтобы открыть личный кабинет.</p><form class="form" onsubmit="submitAuth(event,setPassword)"><label>Новый пароль<input name="password" type="password" required minlength="12" maxlength="128" autocomplete="new-password" aria-describedby="password-help"></label><small id="password-help" class="muted">От 12 символов. Должен отличаться от временного.</small><label>Повторите новый пароль<input name="confirmPassword" type="password" required minlength="12" maxlength="128" autocomplete="new-password"></label><div class="form-error" role="alert" hidden></div><button class="primary" type="submit">Сохранить пароль и открыть кабинет →</button><button class="quiet" type="button" onclick="logout()">Выйти</button></form>`)}
async function setPassword(fields){if(fields.password!==fields.confirmPassword)throw Error('Пароли не совпадают');const result=await api('/api/auth/password','POST',fields);authUser=result.user;await refreshAccount();openWorkspace();toast('Новый пароль сохранён')}
async function logout(){try{await api('/api/auth/logout','POST',{});authUser=null;accountData={orders:[],bookings:[],owners:[],restaurants:[]};db.orders=[];db.bookings=[];if($('#modal').open)$('#modal').close();if(accountRoute)renderAccount();else{page='discover';render();toast('Вы вышли из аккаунта')}}catch(e){toast(e.message)}}
let catalogNextCursor=null,catalogTotal=0,catalogRequest=0,catalogLoading=false,catalogTimer;
function catalogParams(cursor){const params=new URLSearchParams({limit:'24'});if(accountRoute&&authUser&&!authUser.mustChangePassword){params.set('manage','1');if(typeof adminSection!=='undefined'&&adminSection==='certificates')params.set('certificates','1')}else{if(query)params.set('query',query);for(const c of selectedCuisines)params.append('cuisine',c);if(category!=='Все'&&!selectedCuisines.length)params.append('cuisine',category);if(halalOnly)params.set('halal','1');if(page==='favorites'&&db.favorites.length)params.set('ids',db.favorites.slice(0,100).join(','))}if(cursor)params.set('cursor',cursor);return params}
async function refreshCatalog(append=false){const version=++catalogRequest,result=await api('/api/catalog?'+catalogParams(append?catalogNextCursor:null));if(version!==catalogRequest)return;db.restaurants=append?Array.from(new Map([...db.restaurants,...result.restaurants].map(r=>[r.id,r])).values()):result.restaurants;Object.assign(db.menus,result.menus||{});catalogNextCursor=result.nextCursor||null;catalogTotal=result.total??result.restaurants.length;if(Array.isArray(result.cuisines))cuisineTypes=result.cuisines;save()}
function scheduleCatalogRefresh(){clearTimeout(catalogTimer);catalogTimer=setTimeout(async()=>{try{await refreshCatalog();render()}catch(error){toast(error.message)}},180)}
async function loadMoreRestaurants(){if(catalogLoading||!catalogNextCursor)return;catalogLoading=true;try{await refreshCatalog(true);render()}catch(error){toast(error.message)}finally{catalogLoading=false}}
function moreRestaurantsButton(){return catalogNextCursor?'<div class="load-more"><button class="secondary" onclick="loadMoreRestaurants()">Показать ещё</button></div>':''}
async function fetchMenu(id){const result=await api('/api/restaurants/'+encodeURIComponent(id)+'/menu');db.menus[id]=result.menu;const index=db.restaurants.findIndex(r=>r.id===id);if(index<0)db.restaurants.push(result.restaurant);else db.restaurants[index]=result.restaurant;return result.restaurant}
openRestaurant=async function(id){try{await fetchMenu(id);current=id;selectedDishCategory='Все блюда';page='detail';render();window.scrollTo({top:0,behavior:'smooth'})}catch(error){toast(error.message)}};

async function refreshAccount(){accountData=await api('/api/account');authUser=accountData.user;db.orders=accountData.orders;db.bookings=accountData.bookings}
async function refreshHistory(){const result=await api('/api/my');db.orders=result.orders;db.bookings=result.bookings}
async function openWorkspace(){try{await refreshCatalog();await refreshAccount();current=authUser.restaurant||db.restaurants[0]?.id;page=authUser.role==='admin'?'admin':'business';render()}catch(e){if(e.status===401){authUser=null;renderAccount()}else if(e.status===403){changePassword()}else toast(e.message)}}
function openAdmin(){page='admin';render()}
// Keep the existing guest interface, but make server-side checks authoritative.
async function nav(p){if(['profile','clientlogin'].includes(p))return;if(['business','admin'].includes(p)&&!authUser){location.href='/account';return}page=p;query='';try{if(['orders','bookings'].includes(p))await refreshHistory();if(['business','admin'].includes(p)){await refreshAccount();if(authUser.mustChangePassword){changePassword();return}}render();window.scrollTo({top:0,behavior:'smooth'})}catch(e){toast(e.message)}};
async function submitOrder(e){e.preventDefault();if(orderSubmitting)return;if(!cartRestaurant||!Object.keys(cart).length){toast('Добавьте блюда в корзину');return}const form=e.target,button=form.querySelector('button');orderSubmitting=true;button.disabled=true;try{let fields=Object.fromEntries(new FormData(form));await api('/api/orders','POST',{...fields,restaurant:cartRestaurant,mode:mode==='pickup'?'pickup':'delivery',items:Object.entries(cart).map(([id,qty])=>({id,qty}))});cart={};cartRestaurant=null;persistCart();$('#modal').close();await nav('orders');toast('Заказ поступил в кабинет ресторана')}catch(error){toast(error.message)}finally{orderSubmitting=false;button.disabled=false}};
async function submitBooking(e,id){e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{await api('/api/bookings','POST',{...Object.fromEntries(new FormData(e.target)),restaurant:id});$('#modal').close();await nav('bookings');toast('Заявка на столик отправлена')}catch(error){toast(error.message)}finally{button.disabled=false}};
async function cancel(kind,id){try{await api(`/api/${kind}/${id}`,'PATCH',{cancel:true});await refreshHistory();render();toast('Заявка отменена')}catch(e){toast(e.message)}};
async function updateStatus(kind,id,status){try{await api(`/api/${kind}/${id}`,'PATCH',{status});await refreshAccount();render();toast('Статус обновлён')}catch(e){toast(e.message);await refreshAccount();render()}};
function dishPhotoInput(required=false,img=null){return `<label class="dish-photo-field">Фото блюда<img class="dish-photo-preview" src="${photo(img,250)}" alt="Фото блюда"><input name="photoFile" type="file" accept="image/jpeg,image/png,image/webp" ${required?'required':''} onchange="previewDishPhoto(this)"><small>Фото сохраняется вместе с блюдом.</small></label>`}
function previewDishPhoto(input){const img=input.closest('label').querySelector('img'),file=input.files[0];if(img.dataset.previewUrl)URL.revokeObjectURL(img.dataset.previewUrl);if(file){const url=URL.createObjectURL(file);img.dataset.previewUrl=url;img.src=url}}
async function dishFields(form){const values=Object.fromEntries(new FormData(form));delete values.photoFile;const translations={};for(const lang of ['kk','ru','en']){const name=values['name_'+lang],desc=values['desc_'+lang];if(name?.trim())translations[lang]={name:name.trim(),desc:desc||''};delete values['name_'+lang];delete values['desc_'+lang]}if(Object.keys(translations).length){values.translations=translations;values.name=translations.ru?.name||translations.kk?.name||translations.en?.name;values.desc=translations.ru?.desc||translations.kk?.desc||translations.en?.desc}const file=form.elements.photoFile?.files[0];if(!file)return values;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10000000)throw Error('Загрузите фото JPEG или PNG');const button=form.querySelector('button');button.disabled=true;try{const bitmap=await createImageBitmap(file),ratio=Math.min(1,1200/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();let blob;for(const quality of [.85,.7,.5,.3]){blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',quality));if(blob&&blob.size<=400000)break}if(!blob||blob.size>400000)throw Error('Фото слишком большое');const response=await fetch(`/api/restaurants/${current}/photos`,{method:'POST',headers:{'Content-Type':'image/jpeg'},body:blob,credentials:'same-origin'}),result=await response.json();if(!response.ok)throw Error(result.error);values.img=result.url;return values}finally{button.disabled=false}}
async function saveDish(e,id){e.preventDefault();try{await api(`/api/restaurants/${current}/menu`,'POST',{...await dishFields(e.target),id});await refreshCatalog();await fetchMenu(current);$('#modal').close();render();toast('Блюдо обновлено')}catch(error){toast(error.message)}};
async function submitDish(e){e.preventDefault();try{await api(`/api/restaurants/${current}/menu`,'POST',await dishFields(e.target));await refreshCatalog();await fetchMenu(current);$('#modal').close();render();toast('Блюдо добавлено')}catch(error){toast(error.message)}};
const editRestaurantModal=newRestaurant;
const bookingModal=book;
book=async function(id){try{await fetchMenu(id);bookingModal(id)}catch(error){toast(error.message)}};
newRestaurant=function(id){if(id){if(authUser?.role==='admin'){editPartnerProfile(id);return}editRestaurantModal(id);return}registerAsAdmin=true;modal('Регистрация заведения',`<p>Владелец получит логин, временный пароль и ссылку на личный кабинет.</p>${registrationForm()}`)};
async function submitRestaurant(e,id){e.preventDefault();try{await api(`/api/restaurants/${id}`,'PATCH',{...Object.fromEntries(new FormData(e.target)),cuisines:new FormData(e.target).getAll('cuisines'),halalEnabled:e.target.elements.halalEnabled.checked});await refreshCatalog();await refreshAccount();$('#modal').close();render();toast('Изменения сохранены')}catch(error){toast(error.message)}};
function admin(){return `<div class="subheading"><div><div class="eyebrow">УПРАВЛЕНИЕ ПЛАТФОРМОЙ</div><h1>Зарегистрированные заведения</h1><p>У каждого заведения свой владелец и закрытый личный кабинет.</p></div><button class="primary" onclick="newRestaurant()">+ Зарегистрировать заведение</button></div><div class="stats"><div class="stat"><small>Заведения</small><strong>${accountData.stats?.restaurants??db.restaurants.length}</strong><small>На платформе</small></div></div><div class="panel tablewrap"><table class="table"><thead><tr><th>Заведение</th><th>Владелец</th><th>Статус</th><th>Халал</th><th>Управление</th></tr></thead><tbody>${db.restaurants.map(r=>{const owner=accountData.owners.find(o=>o.restaurant===r.id);return `<tr><td><strong>${esc(r.name)}</strong><br>${esc(r.address)}</td><td>${esc(owner?.name||'—')}<br><span class="muted">${esc(owner?.email||'')}</span></td><td>${restaurantStatusBadge(r)}<br><span class="muted">${owner?.delivery==='local'?'Письмо в локальной почте':'Письмо передано сервису'}</span></td><td>${halalAdminCell(r)}</td><td>${restaurantManagementButtons(r)}</td></tr>`}).join('')}</tbody></table></div>${moreRestaurantsButton()}`};
async function start(){try{const result=await api('/api/auth/session');authUser=result.user;localMailMode=result.localMail;await refreshCatalog();const savedCart=JSON.parse(localStorage.getItem('dayin-cart')||'null');if(savedCart?.restaurant){try{await fetchMenu(savedCart.restaurant)}catch{}}restoreCart();if(location.pathname==='/register')registration();else if(accountRoute)renderAccount();else{await refreshHistory();const match=location.pathname.match(/^\/menu\/([^/]+)$/);if(match){const id=decodeURIComponent(match[1]);await fetchMenu(id);current=id;page='detail'}render()}}catch(e){authFrame(`<h1>Сервер недоступен</h1><p>${esc(e.message)}</p><button class="primary" onclick="start()">Попробовать ещё раз</button>`)}}
let qrGeneratedFor=null,qrSize=1024;
function qrMenuUrl(){return `${location.origin}/menu/${encodeURIComponent(current)}`}
function qrPanel(){const ready=qrGeneratedFor===current;return `<section class="panel qr-panel"><div class="qr-copy"><div class="eyebrow">МЕНЮ В ОДНО КАСАНИЕ</div><h2>QR-код вашего заведения</h2><p>Гости сканируют код и сразу открывают актуальное меню. При изменении блюд QR-код остаётся прежним.</p><label class="qr-label">Ссылка на меню<div class="qr-link-row"><input aria-label="Ссылка на меню" value="${esc(qrMenuUrl())}" readonly><a class="secondary" href="${esc(qrMenuUrl())}" target="_blank" rel="noopener">Открыть ↗</a></div></label><label class="qr-label">Размер PNG<select class="secondary" onchange="qrSize=Number(this.value)">${[512,1024,2048].map(size=>`<option value="${size}" ${qrSize===size?'selected':''}>${size} × ${size} px</option>`).join('')}</select></label><button class="primary" onclick="generateQr()">${ready?'Обновить QR-код':'Сгенерировать QR-код'}</button><div class="qr-downloads"><button class="secondary" onclick="downloadQr('svg',this)" ${ready?'':'disabled'}>Скачать SVG</button><button class="secondary" onclick="downloadQr('png',this)" ${ready?'':'disabled'}>Скачать PNG</button></div><p class="auth-help">SVG — для печати в любом размере. PNG — для изображений и отправки. Код содержит только публичную ссылку на меню.</p>${['localhost','127.0.0.1'].includes(location.hostname)?'<div class="notice">Сейчас ссылка локальная: телефон её не откроет. После публикации создайте QR-код заново со ссылкой на доступный гостям сайт.</div>':''}</div><div class="qr-preview-wrap"><div class="qr-preview">${ready?`<img id="qr-preview" width="240" height="240" src="/api/restaurants/${encodeURIComponent(current)}/qr?format=svg&size=512" alt="QR-код меню ресторана ${esc(restaurant().name)}" onload="qrPreviewLoaded()" onerror="qrPreviewFailed()"><span id="qr-preview-status" role="status">Создаём QR-код…</span>`:'<div class="qr-placeholder"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><path d="M3 3h6v6H3z M15 3h6v6h-6z M3 15h6v6H3z M15 15h3v3h3v3h-6z M12 3v3 M12 9v3H3 M12 15v6 M18 12h3"/></svg><strong>Здесь появится ваш QR-код</strong><span>Сгенерируйте и скачайте его</span></div>'}</div><strong>${esc(restaurant().name)}</strong><span class="muted">Отсканируйте, чтобы открыть меню</span></div></section>`}
async function generateQr(){try{await api(`/api/restaurants/${encodeURIComponent(current)}/qr`);qrGeneratedFor=current;render()}catch(e){toast(e.message)}}
function qrPreviewLoaded(){const status=$('#qr-preview-status');if(status)status.textContent='QR-код готов'}
function qrPreviewFailed(){const status=$('#qr-preview-status');if(status)status.textContent='Не удалось создать QR-код. Повторите попытку.';qrGeneratedFor=null;document.querySelectorAll('.qr-downloads button').forEach(b=>b.disabled=true)}
async function downloadQr(format,button){button.disabled=true;const old=button.textContent;button.textContent='Подготовка…';try{const response=await fetch(`/api/restaurants/${encodeURIComponent(current)}/qr?format=${format}&size=${qrSize}&download=1`,{credentials:'same-origin'});if(!response.ok){const result=await response.json();throw Error(result.error||'Не удалось скачать QR-код')}const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`dayin-menu-${current}.${format}`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);toast(`QR-код в ${format.toUpperCase()} скачан`)}catch(e){toast(e.message)}finally{button.textContent=old;button.disabled=false}}
function halalState(r){if(!r.halal)return 'none';if(Date.parse(r.halal.validUntil+'T23:59:59+06:00')<Date.now())return 'expired';return r.halal.status}
function halalLabel(r){return ({none:'Не указан',pending:'На проверке',verified:'Подтверждён',rejected:'Не подтверждён',expired:'Срок истёк'})[halalState(r)]||'Не подтверждён'}
function halalBadge(r){return halalState(r)==='verified'?`<button class="halal-badge" onclick="showHalalCertificate('${r.id}')" aria-label="Халал: посмотреть сертификат ресторана ${esc(r.name)}"><svg viewBox="0 0 20 20" fill="none" aria-hidden="true"><circle cx="10" cy="10" r="8" fill="currentColor"/><path d="m6 10 2.5 2.5L14 7" stroke="white" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>Халал</button>`:''}
function showHalalCertificate(id){const r=db.restaurants.find(r=>r.id===id);if(!r?.halal)return;const c=r.halal;modal('Сертификат халал',`<p>${esc(r.name)}</p><dl class="certificate-details"><dt>Статус</dt><dd>${halalLabel(r)}</dd><dt>Орган сертификации</dt><dd>${esc(c.issuer)}</dd><dt>Номер сертификата</dt><dd>${esc(c.number)}</dd><dt>Действителен до</dt><dd>${esc(c.validUntil.split('-').reverse().join('.'))}</dd></dl><a class="primary auth-link" href="${esc(c.certificateUrl)}" target="_blank" rel="noopener noreferrer">Открыть сертификат ↗</a><p class="auth-help">Данные предоставлены заведением. Отметку подтверждает администратор платформы.</p>`)}
function halalSettings(r){const c=r.halal;return `<section class="halal-settings"><h3>Сертификация халал</h3><label class="halal-toggle"><input name="halalEnabled" type="checkbox" ${c?'checked':''} onchange="toggleHalalFields(this)"><span>У заведения есть сертификат халал</span></label><p class="auth-help">Статус: <strong>${halalLabel(r)}</strong>. Галочка в каталоге появляется после проверки администратором.</p><fieldset id="halal-fields" ${c?'':'disabled hidden'}><label>Орган сертификации<input name="halalIssuer" value="${esc(c?.issuer||'')}" required maxlength="120" placeholder="Название организации"></label><label>Номер сертификата<input name="halalNumber" value="${esc(c?.number||'')}" required maxlength="80"></label><label>Действителен до<input name="halalValidUntil" type="date" value="${esc(c?.validUntil||'')}" required min="${new Date().toISOString().slice(0,10)}"></label><label>Ссылка на сертификат<input name="halalCertificateUrl" type="url" value="${esc(c?.certificateUrl||'')}" required maxlength="1000" placeholder="https://…"><small class="muted">Ссылка на документ для проверки и просмотра гостями.</small></label></fieldset></section>`}
function toggleHalalFields(checkbox){const fields=$('#halal-fields');fields.disabled=!checkbox.checked;fields.hidden=!checkbox.checked}
function halalAdminCell(r){return `<span class="status">${halalLabel(r)}</span>${r.halal?`<div class="halal-review"><button class="quiet" onclick="showHalalCertificate('${r.id}')">Сертификат ↗</button>${!['verified','expired'].includes(halalState(r))?`<button class="quiet" onclick="reviewHalal('${r.id}','approve',this)">Подтвердить</button>`:''}${['pending','verified'].includes(halalState(r))?`<button class="delete" onclick="reviewHalal('${r.id}','reject',this)">${halalState(r)==='verified'?'Снять отметку':'Отклонить'}</button>`:''}</div>`:''}`}
async function reviewHalal(id,action,button){button.disabled=true;try{await api(`/api/restaurants/${id}/halal-review`,'PATCH',{action});await refreshCatalog();await refreshAccount();render();toast(action==='approve'?'Сертификат подтверждён. Отметка добавлена.':'Отметка халал отключена.')}catch(e){toast(e.message);button.disabled=false}}

